-- Table console_views
CREATE TABLE `console_views` (
  `id` char(36) NOT NULL,
  `user_id` char(36) NOT NULL,
  `kind` varchar(16) NOT NULL,
  `name` varchar(80) NOT NULL,
  `query` varchar(512) NOT NULL,
  `position` int(11) NOT NULL DEFAULT 0,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  `deleted_at` datetime(3) DEFAULT NULL,
  `version` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `console_views_name` (`user_id`,`kind`,`name`),
  KEY `console_views_owner` (`user_id`,`kind`,`position`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table content_fields
CREATE TABLE `content_fields` (
  `id` char(36) NOT NULL,
  `field_key` varchar(191) NOT NULL,
  `label` varchar(255) NOT NULL DEFAULT '',
  `role` varchar(32) NOT NULL DEFAULT 'text',
  `route` varchar(191) NOT NULL DEFAULT '',
  `section_id` varchar(120) NOT NULL DEFAULT '',
  `default_ar` text DEFAULT NULL,
  `default_en` text DEFAULT NULL,
  `draft_ar` text DEFAULT NULL,
  `draft_en` text DEFAULT NULL,
  `pub_ar` text DEFAULT NULL,
  `pub_en` text DEFAULT NULL,
  `status` varchar(32) NOT NULL DEFAULT 'published',
  `enabled` tinyint(1) NOT NULL DEFAULT 1,
  `source_file` varchar(255) DEFAULT NULL,
  `source_line` int(11) DEFAULT NULL,
  `orphaned_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  `created_by` char(36) DEFAULT NULL,
  `updated_by` char(36) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `version` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `content_fields_key` (`field_key`),
  KEY `content_fields_route` (`route`,`section_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table ctas
CREATE TABLE `ctas` (
  `id` char(36) NOT NULL,
  `cta_key` varchar(120) NOT NULL,
  `label_ar` varchar(255) NOT NULL DEFAULT '',
  `label_en` varchar(255) NOT NULL DEFAULT '',
  `placement` varchar(191) NOT NULL DEFAULT '',
  `cta_type` varchar(32) NOT NULL DEFAULT 'whatsapp',
  `target` varchar(600) NOT NULL DEFAULT '',
  `enabled` tinyint(1) NOT NULL DEFAULT 1,
  `position` int(11) NOT NULL DEFAULT 0,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  `created_by` char(36) DEFAULT NULL,
  `updated_by` char(36) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `version` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ctas_key` (`cta_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table cta_actions
CREATE TABLE `cta_actions` (
  `id` char(36) NOT NULL,
  `cta_id` char(36) NOT NULL,
  `position` int(11) NOT NULL DEFAULT 0,
  `action_type` varchar(32) NOT NULL,
  `config` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`config`)),
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  PRIMARY KEY (`id`),
  KEY `cta_actions_cta` (`cta_id`,`position`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table hero_settings
CREATE TABLE `hero_settings` (
  `id` tinyint(4) NOT NULL,
  `autoplay` tinyint(1) NOT NULL DEFAULT 1,
  `interval_ms` int(11) NOT NULL DEFAULT 7000,
  `fade_ms` int(11) NOT NULL DEFAULT 1200,
  `pause_on_hover` tinyint(1) NOT NULL DEFAULT 1,
  `dots` tinyint(1) NOT NULL DEFAULT 0,
  `arrows` tinyint(1) NOT NULL DEFAULT 0,
  `looping` tinyint(1) NOT NULL DEFAULT 1,
  `updated_by` char(36) DEFAULT NULL,
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  `version` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

