-- Table hero_slides
CREATE TABLE `hero_slides` (
  `id` char(36) NOT NULL,
  `position` int(11) NOT NULL DEFAULT 0,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `image` varchar(512) NOT NULL,
  `image_mobile` varchar(512) DEFAULT NULL,
  `alt_ar` varchar(255) NOT NULL DEFAULT '',
  `alt_en` varchar(255) NOT NULL DEFAULT '',
  `heading_ar` varchar(255) DEFAULT NULL,
  `heading_en` varchar(255) DEFAULT NULL,
  `sub_ar` varchar(500) DEFAULT NULL,
  `sub_en` varchar(500) DEFAULT NULL,
  `cta_label_ar` varchar(120) DEFAULT NULL,
  `cta_label_en` varchar(120) DEFAULT NULL,
  `cta_href_ar` varchar(512) DEFAULT NULL,
  `cta_href_en` varchar(512) DEFAULT NULL,
  `starts_at` datetime(3) DEFAULT NULL,
  `ends_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  `created_by` char(36) DEFAULT NULL,
  `updated_by` char(36) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `version` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `hero_slides_order` (`deleted_at`,`active`,`position`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table integrations
CREATE TABLE `integrations` (
  `id` char(36) NOT NULL,
  `kind` varchar(32) NOT NULL,
  `name` varchar(191) NOT NULL DEFAULT '',
  `config` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`config`)),
  `enabled` tinyint(1) NOT NULL DEFAULT 0,
  `schema_hash` char(64) NOT NULL DEFAULT '',
  `last_error` varchar(1000) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  `created_by` char(36) DEFAULT NULL,
  `updated_by` char(36) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `version` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `integrations_kind` (`kind`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table jobs
CREATE TABLE `jobs` (
  `id` char(36) NOT NULL,
  `kind` varchar(64) NOT NULL,
  `payload` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`payload`)),
  `status` varchar(32) NOT NULL DEFAULT 'queued',
  `run_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `finished_at` datetime(3) DEFAULT NULL,
  `error` varchar(1000) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  PRIMARY KEY (`id`),
  KEY `jobs_due` (`status`,`run_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table leads
CREATE TABLE `leads` (
  `id` char(36) NOT NULL,
  `source` varchar(64) NOT NULL DEFAULT 'contact-form',
  `form_id` varchar(64) NOT NULL DEFAULT '',
  `name` varchar(255) NOT NULL DEFAULT '',
  `phone` varchar(64) NOT NULL DEFAULT '',
  `email` varchar(255) NOT NULL DEFAULT '',
  `message` text DEFAULT NULL,
  `fields` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`fields`)),
  `status` varchar(32) NOT NULL DEFAULT 'new',
  `assignee_id` char(36) DEFAULT NULL,
  `locale` varchar(5) NOT NULL DEFAULT 'ar',
  `page_path` varchar(512) NOT NULL DEFAULT '',
  `landing_page` varchar(512) NOT NULL DEFAULT '',
  `first_referrer` varchar(512) NOT NULL DEFAULT '',
  `gclid` varchar(255) NOT NULL DEFAULT '',
  `fbclid` varchar(255) NOT NULL DEFAULT '',
  `device` varchar(16) NOT NULL DEFAULT 'unknown',
  `utm_source` varchar(191) NOT NULL DEFAULT '',
  `utm_medium` varchar(191) NOT NULL DEFAULT '',
  `utm_campaign` varchar(191) NOT NULL DEFAULT '',
  `utm_term` varchar(191) NOT NULL DEFAULT '',
  `utm_content` varchar(191) NOT NULL DEFAULT '',
  `city` varchar(96) NOT NULL DEFAULT '',
  `day` date DEFAULT NULL,
  `session_hash` char(64) DEFAULT NULL,
  `visitor_hash` char(64) DEFAULT NULL,
  `referrer` varchar(512) NOT NULL DEFAULT '',
  `utm` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`utm`)),
  `idempotency_key` varchar(120) NOT NULL DEFAULT '',
  `sheets_sent_at` datetime(3) DEFAULT NULL,
  `spam` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  `created_by` char(36) DEFAULT NULL,
  `updated_by` char(36) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `version` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `leads_idempotency` (`idempotency_key`),
  KEY `leads_status` (`status`,`created_at`),
  KEY `leads_created` (`created_at`),
  KEY `leads_campaign` (`utm_source`,`created_at`),
  KEY `leads_gclid` (`gclid`),
  KEY `leads_day` (`day`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table lead_notes
CREATE TABLE `lead_notes` (
  `id` char(36) NOT NULL,
  `lead_id` char(36) NOT NULL,
  `author_id` char(36) NOT NULL,
  `body` varchar(2000) NOT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  PRIMARY KEY (`id`),
  KEY `lead_notes_lead` (`lead_id`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

