-- Table login_attempts
CREATE TABLE `login_attempts` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `email_lc` varchar(255) NOT NULL DEFAULT '',
  `ip_hash` char(64) NOT NULL DEFAULT '',
  `success` tinyint(1) NOT NULL,
  `attempted_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  PRIMARY KEY (`id`),
  KEY `login_attempts_window` (`ip_hash`,`attempted_at`),
  KEY `login_attempts_email` (`email_lc`,`attempted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table media
CREATE TABLE `media` (
  `id` char(36) NOT NULL,
  `path` varchar(512) NOT NULL,
  `filename` varchar(255) NOT NULL,
  `mime` varchar(100) NOT NULL DEFAULT '',
  `width` int(11) NOT NULL DEFAULT 0,
  `height` int(11) NOT NULL DEFAULT 0,
  `size_bytes` bigint(20) NOT NULL DEFAULT 0,
  `sha256` char(64) NOT NULL DEFAULT '',
  `alt_ar` varchar(500) NOT NULL DEFAULT '',
  `alt_en` varchar(500) NOT NULL DEFAULT '',
  `folder_id` char(36) DEFAULT NULL,
  `legacy_url` varchar(600) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  `created_by` char(36) DEFAULT NULL,
  `updated_by` char(36) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `version` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `media_path` (`path`),
  KEY `media_sha` (`sha256`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table media_folders
CREATE TABLE `media_folders` (
  `id` char(36) NOT NULL,
  `name` varchar(191) NOT NULL,
  `parent_id` char(36) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  PRIMARY KEY (`id`),
  KEY `media_folders_parent` (`parent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table notifications
CREATE TABLE `notifications` (
  `id` char(36) NOT NULL,
  `user_id` char(36) DEFAULT NULL,
  `kind` varchar(64) NOT NULL,
  `title` varchar(500) NOT NULL DEFAULT '',
  `body` varchar(2000) NOT NULL DEFAULT '',
  `entity_type` varchar(32) DEFAULT NULL,
  `entity_id` varchar(191) DEFAULT NULL,
  `read_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  PRIMARY KEY (`id`),
  KEY `notifications_user` (`user_id`,`read_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table offers
CREATE TABLE `offers` (
  `id` char(36) NOT NULL,
  `slug` varchar(191) NOT NULL,
  `status` varchar(32) NOT NULL DEFAULT 'draft',
  `name_ar` varchar(500) NOT NULL DEFAULT '',
  `name_en` varchar(500) NOT NULL DEFAULT '',
  `excerpt_ar` varchar(1000) NOT NULL DEFAULT '',
  `excerpt_en` varchar(1000) NOT NULL DEFAULT '',
  `body_ar` mediumtext DEFAULT NULL,
  `body_en` mediumtext DEFAULT NULL,
  `pub_name_ar` varchar(500) NOT NULL DEFAULT '',
  `pub_name_en` varchar(500) NOT NULL DEFAULT '',
  `pub_excerpt_ar` varchar(1000) NOT NULL DEFAULT '',
  `pub_excerpt_en` varchar(1000) NOT NULL DEFAULT '',
  `pub_body_ar` mediumtext DEFAULT NULL,
  `pub_body_en` mediumtext DEFAULT NULL,
  `price` decimal(12,2) DEFAULT NULL,
  `regular_price` decimal(12,2) DEFAULT NULL,
  `currency` varchar(8) NOT NULL DEFAULT 'EGP',
  `on_sale` tinyint(1) NOT NULL DEFAULT 0,
  `images` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`images`)),
  `applicable_services` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`applicable_services`)),
  `enabled` tinyint(1) NOT NULL DEFAULT 1,
  `starts_at` date DEFAULT NULL,
  `ends_at` date DEFAULT NULL,
  `position` int(11) NOT NULL DEFAULT 0,
  `published_at` datetime(3) DEFAULT NULL,
  `legacy_id` varchar(64) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  `created_by` char(36) DEFAULT NULL,
  `updated_by` char(36) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `version` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `offers_slug` (`slug`),
  KEY `offers_enabled` (`enabled`,`position`),
  KEY `offers_public` (`status`,`deleted_at`,`position`,`slug`),
  KEY `offers_live` (`enabled`,`starts_at`,`ends_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

