-- Table outbox
CREATE TABLE `outbox` (
  `id` char(36) NOT NULL,
  `kind` varchar(64) NOT NULL,
  `payload` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`payload`)),
  `attempts` int(11) NOT NULL DEFAULT 0,
  `next_attempt_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `sent_at` datetime(3) DEFAULT NULL,
  `last_error` varchar(1000) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  PRIMARY KEY (`id`),
  KEY `outbox_due` (`sent_at`,`next_attempt_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table pages
CREATE TABLE `pages` (
  `id` char(36) NOT NULL,
  `route` varchar(191) NOT NULL,
  `status` varchar(32) NOT NULL DEFAULT 'draft',
  `title_ar` varchar(500) NOT NULL DEFAULT '',
  `title_en` varchar(500) NOT NULL DEFAULT '',
  `content_ar` mediumtext DEFAULT NULL,
  `content_en` mediumtext DEFAULT NULL,
  `data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`data`)),
  `pub_title_ar` varchar(500) NOT NULL DEFAULT '',
  `pub_title_en` varchar(500) NOT NULL DEFAULT '',
  `pub_content_ar` mediumtext DEFAULT NULL,
  `pub_content_en` mediumtext DEFAULT NULL,
  `pub_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`pub_data`)),
  `enabled` tinyint(1) NOT NULL DEFAULT 1,
  `redirect_to` varchar(512) DEFAULT NULL,
  `published_at` datetime(3) DEFAULT NULL,
  `legacy_id` varchar(64) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  `created_by` char(36) DEFAULT NULL,
  `updated_by` char(36) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `version` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `pages_route` (`route`),
  KEY `pages_public` (`status`,`deleted_at`,`route`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

