-- Table permission_grants
CREATE TABLE `permission_grants` (
  `id` char(36) NOT NULL,
  `user_id` char(36) NOT NULL,
  `resource` varchar(64) NOT NULL,
  `action` varchar(32) NOT NULL,
  `scope` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`scope`)),
  `granted_by` char(36) NOT NULL,
  `expires_at` datetime(3) DEFAULT NULL,
  `revoked_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  PRIMARY KEY (`id`),
  KEY `permission_grants_user` (`user_id`,`resource`,`action`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table permission_requests
CREATE TABLE `permission_requests` (
  `id` char(36) NOT NULL,
  `user_id` char(36) NOT NULL,
  `resource` varchar(64) NOT NULL,
  `action` varchar(32) NOT NULL,
  `scope` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`scope`)),
  `reason` varchar(1000) NOT NULL DEFAULT '',
  `status` varchar(32) NOT NULL DEFAULT 'pending',
  `requested_days` int(11) DEFAULT NULL,
  `decided_by` char(36) DEFAULT NULL,
  `decided_at` datetime(3) DEFAULT NULL,
  `decision_note` varchar(1000) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  `version` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `permission_requests_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table redirects
CREATE TABLE `redirects` (
  `id` char(36) NOT NULL,
  `source_path` varchar(512) NOT NULL,
  `target_path` varchar(512) NOT NULL,
  `status_code` int(11) NOT NULL DEFAULT 301,
  `match_type` varchar(16) NOT NULL DEFAULT 'exact',
  `enabled` tinyint(1) NOT NULL DEFAULT 1,
  `hits` int(11) NOT NULL DEFAULT 0,
  `note` varchar(500) NOT NULL DEFAULT '',
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  `created_by` char(36) DEFAULT NULL,
  `updated_by` char(36) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `version` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `redirects_source` (`source_path`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table revisions
CREATE TABLE `revisions` (
  `id` char(36) NOT NULL,
  `entity_type` varchar(32) NOT NULL,
  `entity_id` varchar(191) NOT NULL,
  `revision` int(11) NOT NULL,
  `snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`snapshot`)),
  `author_id` char(36) DEFAULT NULL,
  `author_email` varchar(255) NOT NULL DEFAULT '',
  `note` varchar(500) NOT NULL DEFAULT '',
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `revisions_unique` (`entity_type`,`entity_id`,`revision`),
  KEY `revisions_entity` (`entity_type`,`entity_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

