-- Table section_state
CREATE TABLE `section_state` (
  `id` char(36) NOT NULL,
  `route` varchar(191) NOT NULL,
  `section_id` varchar(120) NOT NULL,
  `label` varchar(255) NOT NULL DEFAULT '',
  `enabled` tinyint(1) NOT NULL DEFAULT 1,
  `position` int(11) NOT NULL DEFAULT 0,
  `variant` varchar(64) DEFAULT NULL,
  `animation` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`animation`)),
  `publish_at` datetime(3) DEFAULT NULL,
  `unpublish_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  `created_by` char(36) DEFAULT NULL,
  `updated_by` char(36) DEFAULT NULL,
  `version` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `section_state_key` (`route`,`section_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table seo_entries
CREATE TABLE `seo_entries` (
  `id` char(36) NOT NULL,
  `entity_type` varchar(32) NOT NULL,
  `entity_id` varchar(191) NOT NULL DEFAULT '',
  `locale` varchar(5) NOT NULL,
  `title` varchar(500) NOT NULL DEFAULT '',
  `description` varchar(1000) NOT NULL DEFAULT '',
  `canonical` varchar(512) DEFAULT NULL,
  `robots` varchar(120) DEFAULT NULL,
  `og_title` varchar(500) DEFAULT NULL,
  `og_description` varchar(1000) DEFAULT NULL,
  `og_image` varchar(512) DEFAULT NULL,
  `twitter_card` varchar(32) DEFAULT NULL,
  `hreflang` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`hreflang`)),
  `jsonld` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`jsonld`)),
  `head_tags` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`head_tags`)),
  `draft` tinyint(1) NOT NULL DEFAULT 1,
  `published_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  `created_by` char(36) DEFAULT NULL,
  `updated_by` char(36) DEFAULT NULL,
  `version` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `seo_entry_key` (`entity_type`,`entity_id`,`locale`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table sessions
CREATE TABLE `sessions` (
  `id` char(36) NOT NULL,
  `token_hash` char(64) NOT NULL,
  `user_id` char(36) NOT NULL,
  `csrf_hash` char(64) NOT NULL,
  `ip_hash` char(64) NOT NULL DEFAULT '',
  `user_agent` varchar(400) NOT NULL DEFAULT '',
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `last_seen_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `expires_at` datetime(3) NOT NULL,
  `revoked_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `sessions_token` (`token_hash`),
  KEY `sessions_user` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table settings
CREATE TABLE `settings` (
  `group_name` varchar(64) NOT NULL,
  `setting_key` varchar(120) NOT NULL,
  `value` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`value`)),
  `default_value` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`default_value`)),
  `is_secret` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  `updated_by` char(36) DEFAULT NULL,
  `version` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`group_name`,`setting_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table snapshots
CREATE TABLE `snapshots` (
  `id` char(36) NOT NULL,
  `label` varchar(255) NOT NULL DEFAULT '',
  `kind` varchar(32) NOT NULL DEFAULT 'publish',
  `payload` longblob NOT NULL,
  `payload_bytes` int(11) NOT NULL DEFAULT 0,
  `entity_count` int(11) NOT NULL DEFAULT 0,
  `is_current` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `created_by` char(36) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `snapshots_current` (`is_current`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table stats_cta_daily
CREATE TABLE `stats_cta_daily` (
  `day` date NOT NULL,
  `cta_key` varchar(120) NOT NULL,
  `clicks` bigint(20) NOT NULL DEFAULT 0,
  UNIQUE KEY `stats_cta_key` (`day`,`cta_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table stats_daily
CREATE TABLE `stats_daily` (
  `day` date NOT NULL,
  `path` varchar(512) NOT NULL,
  `locale` varchar(5) NOT NULL DEFAULT '',
  `views` bigint(20) NOT NULL DEFAULT 0,
  `visitors` bigint(20) NOT NULL DEFAULT 0,
  PRIMARY KEY (`day`,`path`,`locale`),
  KEY `stats_daily_day` (`day`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table stats_events
CREATE TABLE `stats_events` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `day` date NOT NULL,
  `hour` tinyint(3) unsigned DEFAULT NULL,
  `event_type` varchar(24) NOT NULL DEFAULT 'pageview',
  `path` varchar(512) NOT NULL,
  `locale` varchar(5) NOT NULL DEFAULT '',
  `referrer_host` varchar(191) NOT NULL DEFAULT '',
  `utm_source` varchar(191) NOT NULL DEFAULT '',
  `utm_medium` varchar(191) NOT NULL DEFAULT '',
  `utm_campaign` varchar(191) NOT NULL DEFAULT '',
  `utm_term` varchar(191) NOT NULL DEFAULT '',
  `utm_content` varchar(191) NOT NULL DEFAULT '',
  `gclid` varchar(255) NOT NULL DEFAULT '',
  `fbclid` varchar(255) NOT NULL DEFAULT '',
  `landing` varchar(512) NOT NULL DEFAULT '',
  `session_hash` char(64) DEFAULT NULL,
  `city` varchar(96) NOT NULL DEFAULT '',
  `meta` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`meta`)),
  `device` varchar(16) NOT NULL DEFAULT 'unknown',
  `cta_key` varchar(120) NOT NULL DEFAULT '',
  `visitor_hash` char(64) DEFAULT NULL,
  `bot` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  PRIMARY KEY (`id`),
  KEY `stats_day_path` (`day`,`path`),
  KEY `stats_day_type` (`day`,`event_type`),
  KEY `stats_created` (`created_at`),
  KEY `stats_events_source` (`day`,`utm_source`),
  KEY `stats_events_session` (`session_hash`),
  KEY `stats_events_hour` (`day`,`hour`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table stats_geo_daily
CREATE TABLE `stats_geo_daily` (
  `day` date NOT NULL,
  `city` varchar(96) NOT NULL DEFAULT '',
  `views` bigint(20) NOT NULL DEFAULT 0,
  `visitors` bigint(20) NOT NULL DEFAULT 0,
  PRIMARY KEY (`day`,`city`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table stats_named_daily
CREATE TABLE `stats_named_daily` (
  `day` date NOT NULL,
  `event_type` varchar(24) NOT NULL,
  `events` bigint(20) NOT NULL DEFAULT 0,
  `sessions` bigint(20) NOT NULL DEFAULT 0,
  PRIMARY KEY (`day`,`event_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table stats_referrers_daily
CREATE TABLE `stats_referrers_daily` (
  `day` date NOT NULL,
  `host` varchar(191) NOT NULL,
  `views` bigint(20) NOT NULL DEFAULT 0,
  `visitors` bigint(20) NOT NULL DEFAULT 0,
  PRIMARY KEY (`day`,`host`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table stats_rollup_state
CREATE TABLE `stats_rollup_state` (
  `id` int(11) NOT NULL,
  `last_event_id` bigint(20) NOT NULL DEFAULT 0,
  `last_run_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `stats_rollup_state` (`id`, `last_event_id`, `last_run_at`, `updated_at`) VALUES
(1, CONVERT(0x30 USING utf8mb4), NULL, CONVERT(0x323032362d31312d30362030323a30333a30342e303538 USING utf8mb4));

-- Table stats_sources_daily
CREATE TABLE `stats_sources_daily` (
  `day` date NOT NULL,
  `source` varchar(96) NOT NULL DEFAULT '',
  `medium` varchar(96) NOT NULL DEFAULT '',
  `campaign` varchar(128) NOT NULL DEFAULT '',
  `views` bigint(20) NOT NULL DEFAULT 0,
  `visitors` bigint(20) NOT NULL DEFAULT 0,
  PRIMARY KEY (`day`,`source`,`medium`,`campaign`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table theme_tokens
CREATE TABLE `theme_tokens` (
  `token` varchar(64) NOT NULL,
  `label` varchar(191) NOT NULL DEFAULT '',
  `group_name` varchar(64) NOT NULL DEFAULT 'color',
  `light_value` varchar(255) NOT NULL DEFAULT '',
  `dark_value` varchar(255) NOT NULL DEFAULT '',
  `source_value` varchar(255) NOT NULL DEFAULT '',
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  `updated_by` char(36) DEFAULT NULL,
  `version` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`token`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table users
CREATE TABLE `users` (
  `id` char(36) NOT NULL,
  `email` varchar(255) NOT NULL,
  `email_lc` varchar(255) NOT NULL,
  `password_hash` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL DEFAULT '',
  `locale` varchar(5) NOT NULL DEFAULT 'ar',
  `theme` varchar(16) NOT NULL DEFAULT 'light',
  `status` varchar(32) NOT NULL DEFAULT 'active',
  `must_change_password` tinyint(1) NOT NULL DEFAULT 0,
  `totp_secret` varchar(255) DEFAULT NULL,
  `last_login_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  `created_by` char(36) DEFAULT NULL,
  `updated_by` char(36) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `version` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_lc` (`email_lc`),
  KEY `users_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table user_roles
CREATE TABLE `user_roles` (
  `user_id` char(36) NOT NULL,
  `role_id` char(36) NOT NULL,
  PRIMARY KEY (`user_id`,`role_id`),
  KEY `user_roles_role` (`role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Add the requested initial Owner account; password is stored as a bcrypt hash.
INSERT IGNORE INTO users (id, email, email_lc, password_hash, name, locale, status, must_change_password)
VALUES (UUID(), 'owner@newshamah.shamahclinics.com', LOWER(TRIM('owner@newshamah.shamahclinics.com')), '$2b$12$vfkhmt.yWoFesfOh.p8F.eiWVk2zvWclOszPewCdVMb.dgpwXkA86', 'Site Owner', 'en', 'active', 0);
INSERT IGNORE INTO user_roles (user_id, role_id)
SELECT users.id, roles.id FROM users JOIN roles ON roles.name = 'Owner'
WHERE users.email_lc = LOWER(TRIM('owner@newshamah.shamahclinics.com'));
-- Import the full SQL into an empty database. This result also verifies the initial Owner role.
SELECT users.email, roles.name AS role, roles.is_owner
FROM users
JOIN user_roles ON user_roles.user_id = users.id
JOIN roles ON roles.id = user_roles.role_id
WHERE users.email_lc = LOWER(TRIM('owner@newshamah.shamahclinics.com'))
  AND roles.name = 'Owner';

SET FOREIGN_KEY_CHECKS=1;

-- Patient testimonials (migration 015 + the Editor grant), same statements as database/update-testimonials.sql.
SET NAMES utf8mb4;
START TRANSACTION;

-- 015: the list row the console's "Patient testimonials" screen edits.
INSERT IGNORE INTO lists (id, list_key, label, item_schema, reorderable, is_article_collection)
VALUES ('5f0c7e9a-3b1d-4c62-9a8e-2d4b6f1a7c30', 'testimonials', 'Patient testimonials', '{}', 1, 0);

-- Role catalog sync: every list grant that names `results` (the Editor's) also names `testimonials`.
UPDATE role_permissions
SET scope = JSON_ARRAY_APPEND(scope, '$.lists', 'testimonials')
WHERE resource = 'list'
  AND JSON_VALID(scope)
  AND JSON_CONTAINS(scope, '"results"', '$.lists')
  AND NOT JSON_CONTAINS(scope, '"testimonials"', '$.lists');

INSERT IGNORE INTO app_migrations (name, checksum) VALUES
('015_testimonials_list.sql', '95d80998db303fa73b6edd427dc065b9751da4307b9241738aeecfa67614c233');

COMMIT;

-- What it left behind: one row, and the Editor's grants with testimonials in them.
SELECT list_key, label FROM lists WHERE list_key = 'testimonials';
SELECT action, scope FROM role_permissions WHERE resource = 'list' AND scope LIKE '%testimonials%';

-- Console pack (migrations 016 and 017 + two role grants), same statements as database/update-console-pack.sql.
SET NAMES utf8mb4;
START TRANSACTION;

-- 016: the 404 monitor's table.
CREATE TABLE IF NOT EXISTS not_found_log (
  id CHAR(36) PRIMARY KEY,
  path_hash CHAR(64) NOT NULL,
  path VARCHAR(512) NOT NULL,
  referrer VARCHAR(512) NOT NULL DEFAULT '',
  hits INT NOT NULL DEFAULT 1,
  first_seen_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  last_seen_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  UNIQUE KEY not_found_path (path_hash)
);

-- 017: the list row the console's "Ad landing pages" screen edits.
INSERT IGNORE INTO lists (id, list_key, label, item_schema, reorderable, is_article_collection)
VALUES ('8b2d4f61-7a3c-4e95-b1d0-6c9e2a5f8d47', 'landing', 'Ad landing pages', '{}', 1, 0);

-- Role catalog sync: the SEO role reads redirects (it could already write them).
INSERT INTO role_permissions (id, role_id, resource, action, scope)
SELECT UUID(), r.id, 'redirect', 'read', NULL
FROM roles r
WHERE r.name = 'SEO'
  AND NOT EXISTS (
    SELECT 1 FROM role_permissions p WHERE p.role_id = r.id AND p.resource = 'redirect' AND p.action = 'read'
  );

-- Role catalog sync: every list grant that names `results` (the Editor's) also names `landing`.
UPDATE role_permissions
SET scope = JSON_ARRAY_APPEND(scope, '$.lists', 'landing')
WHERE resource = 'list'
  AND JSON_VALID(scope)
  AND JSON_CONTAINS(scope, '"results"', '$.lists')
  AND NOT JSON_CONTAINS(scope, '"landing"', '$.lists');

INSERT IGNORE INTO app_migrations (name, checksum) VALUES
('016_not_found_log.sql', 'ea03f57d5c770b406470d653d7f34853e162c68dfd51d47f9e04d98378dfb122'),
('017_landing_list.sql', '3783f5eee1c98bbf8725494ef9c2a0c82800ae317a9c7f55181af7de2ea41212');

COMMIT;

-- What it left behind.
SHOW TABLES LIKE 'not_found_log';
SELECT list_key, label FROM lists WHERE list_key = 'landing';
SELECT r.name, p.resource, p.action FROM role_permissions p JOIN roles r ON r.id = p.role_id WHERE p.resource = 'redirect' AND p.action = 'read';
SELECT action, scope FROM role_permissions WHERE resource = 'list' AND scope LIKE '%landing%';
